begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
insert into auth.users(id) values ('00000000-0000-0000-0000-000000000001'), ('00000000-0000-0000-0000-000000000002');
insert into public.staff(id, display_name) values ('00000000-0000-0000-0000-000000000001', 'RPC Test A'), ('00000000-0000-0000-0000-000000000002', 'RPC Test B');
insert into public.shift_periods(id, starts_on, ends_on, deadline) values ('00000000-0000-0000-0000-000000000010', '2099-02-16', '2099-02-28', '2099-02-15T12:00:00+09:00');
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000001', true);
select lives_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[{"work_date":"2099-02-16","slot":"lunch"}]', true)$$, 'Save and submit');
select is((select slot from public.shift_availability where period_id = '00000000-0000-0000-0000-000000000010'), 'lunch', 'Saved value');
select ok((select submitted_at is not null from public.shift_submissions where period_id = '00000000-0000-0000-0000-000000000010'), 'Submitted timestamp persisted');
select throws_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[{"work_date":"2099-03-01","slot":"dinner"}]', true)$$, '42501', null, 'Out-of-period save rejected');
select is((select slot from public.shift_availability where period_id = '00000000-0000-0000-0000-000000000010'), 'lunch', 'Failed replacement rolls back deletions');
select lives_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[]', true)$$, 'All unavailable can submit');
select is((select count(*) from public.shift_availability where period_id = '00000000-0000-0000-0000-000000000010'), 0::bigint, 'Empty submission removes old choices');
select ok((select submitted_at is not null from public.shift_submissions where period_id = '00000000-0000-0000-0000-000000000010'), 'Empty submission retains submitted state');
select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[{"work_date":"2099-02-16","slot":"dinner"}]', false);
select ok((select submitted_at is null from public.shift_submissions where period_id = '00000000-0000-0000-0000-000000000010'), 'Draft clears submitted state');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000002', true);
select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[{"work_date":"2099-02-17","slot":"either"}]', true);
select is((select count(*) from public.shift_availability where period_id = '00000000-0000-0000-0000-000000000010'), 2::bigint, 'Staff can read both submissions');
select is((select slot from public.shift_availability where period_id = '00000000-0000-0000-0000-000000000010' and staff_id = '00000000-0000-0000-0000-000000000001'), 'dinner', 'Saving colleague does not replace first user');
update public.shift_periods set accepting = false where id = '00000000-0000-0000-0000-000000000010';
select throws_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[]', true)$$, '42501', null, 'RPC rejects closed period');
reset role;
update public.staff set active = false where id = '00000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[]', true)$$, '42501', null, 'RPC rejects inactive staff');
set local role anon;
select throws_ok($$select public.save_shift_availability('00000000-0000-0000-0000-000000000010', '[]', true)$$, '42501', null, 'Anonymous cannot execute RPC');
select * from finish();
rollback;
